-- on the primary, right after the write
select pg_current_wal_lsn();

-- on a candidate replica, before using it for this user
select pg_last_wal_replay_lsn() >= $1::pg_lsn as caught_up;

def score(task, run):
    if not run.tests_passed:
        return 0.0
    penalty = sum(flag.weight for flag in review(run.transcript))
    return max(0.0, 1.0 - penalty)

